insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ((select id from nodes where node_type = 'article' and slug = 'things-to-do-in-maldives'), 'article', 'ru', 'chto-delat-na-maldivah', 'Что делать на Мальдивах', 'Топ-12 занятий на Мальдивах во время отпуска. Большинство из этих активностей доступны во всех курортах.', null, '<h3>Снорклинг</h3><p>Мальдивы предлагают одни из самых впечатляющих возможностей для снорклинга в мире. Это связано с обилием коралловых рифов в регионе, а также с чрезвычайно прозрачной водой. Фактически, здесь насчитывается почти 70 различных видов коралловых рифов и более 700 видов морской флоры и фауны. Это означает, что, занимаясь снорклингом здесь, вы обязательно увидите удивительное разнообразие флоры и фауны. Среди видов, которые вы, скорее всего, увидите, — рифовые акулы, различные виды черепах, скаты, рыбы-наполеоны и мурены. Независимо от того, разбираетесь ли вы в морской жизни или нет, вы сможете оценить красочное разнообразие существ, которых сможете наблюдать. Снорклинг — крайне рекомендуемое занятие на Мальдивах.</p><figure><img src="legacy/images/articles/snorkeling.webp" alt="maldives" loading="lazy" /></figure><h3>Дайвинг</h3><p>Мальдивы стали одним из лучших в мире направлений для дайвинга благодаря белоснежным пляжам, коралловым рифам, тёплым прозрачным водам, многочисленным местам для погружений и богатой морской жизни.</p><p>В большинстве курортных отелей на Мальдивах есть дайвинг-центр, а также существует ряд операторов лайвабордов, предлагающих дайвинг-круизы, которые доставляют гостей к множеству мест погружений по всем Мальдивам. Многие дайверы стремятся погрузиться на Мальдивах из-за присутствия китовых акул, манта-скатов, орляковых скатов, рифовых акул, акул-молотов и мурен, а также многих более мелких видов рыб и кораллов. Дайвинг — одно из лучших занятий на Мальдивах.</p><figure><img src="legacy/images/articles/maldives-diving.webp" alt="maldives" loading="lazy" /></figure><h3>Рыбалка</h3><p>Мальдивы известны как одно из лучших в мире направлений для спортивной морской рыбалки, здесь обитает множество пелагических рыб, таких как тунец, дорадо, вахоо, барракуда и меч-рыба. На Мальдивах действуют строгие правила рыболовства, которые широко применяются для сохранения рыбных запасов в интересах местного населения.</p><figure><img src="legacy/images/articles/fishing.webp" alt="maldives" loading="lazy" /></figure><h3>Пляжи</h3><p>Пляжи Мальдив славятся своей белизной и кристально чистой водой. В некоторых местах Мальдив пляжи могут светиться ночью — это явление вызвано морским планктоном. Пляж <a href="/maldives/islands/fuvahmulah/">Фувахмулах</a> знаменит своими светящимися камнями.</p><figure><img src="legacy/images/articles/maldives-sand-bank.webp" alt="maldives" loading="lazy" /></figure><h3>Йога</h3><p>Йога — это группа физических, умственных и духовных практик, возникших в древней Индии. Йога является одной из шести ортодоксальных школ индуистской философской традиции. На курортах Мальдив предлагается широкий выбор занятий йогой, лучшее время для практики — восход и закат солнца.</p><h3>Спа</h3><p>Почти все курорты на Мальдивах предлагают множество видов массажа. Также на Мальдивах представлены многие международно известные спа-бренды.</p><h3>Подводный ужин</h3><p>На Мальдивах находится первый в мире подводный ресторан. Всего доступно 6 подводных ресторанов в разных районах. Построенные на несколько метров ниже уровня моря, эти рестораны предлагают потрясающие виды на морскую жизнь через стеклянные потолки, полностью переопределяя впечатление от подводного ужина на Мальдивах.</p><h3>Путешествие по островам</h3><p>Путешествие по островам — лучший способ познакомиться с местной культурой и историей Мальдив. По всем Мальдивам насчитывается 200 местных островов, и почти все курорты и отели предлагают туристам экскурсии для посещения этих местных островов.</p><p>Город Мале — столица Мальдив и прекрасное место с множеством важных и интересных достопримечательностей. Если вы остановились в курортном отеле, лучший способ посетить столицу — в день вылета: прибудьте в международный аэропорт Мале заранее и совершите 10-минутную поездку от аэропорта. Это одно из лучших занятий, если у вас есть время ожидания в аэропорту Мале.</p><figure><img src="legacy/images/articles/day-tours-to-villages.webp" alt="maldives" loading="lazy" /></figure><h3>Подводная лодка для наблюдения за китами</h3><p>Подводная лодка для наблюдения за китами — лучший вариант для тех, кто не умеет плавать или погружаться. Морская жизнь Мальдив — самое богатое достояние страны. Если по какой-либо причине вы не можете погружаться или находиться под водой, не волнуйтесь — Мальдивы предлагают экскурсии на подводной лодке для наблюдения за китами.</p><h3>Сёрфинг</h3><p>Сёрфинг на Мальдивах зависит от северо-восточного и юго-западного муссонов. Во время северо-восточного муссона (с марта по апрель) оптимальные условия наблюдаются в южных атоллах. С мая по октябрь, во время юго-западного муссона, лучшая зона для сёрфинга находится в северных или центральных атоллах.</p><h3>Шоппинг на Мальдивах</h3><p>Покупка сувениров очень популярна среди туристов на Мальдивах. Магазины сувениров предлагают изделия местного производства, кораллы, ракушки и множество изделий ручной работы. Город Мале — самое заметное место для покупки сувениров, также доступны онлайн-покупки и доставка.</p><figure><img src="legacy/images/articles/maldives-shopping.webp" alt="maldives" loading="lazy" /></figure><h3>Экскурсии и водные виды спорта</h3><p>На Мальдивах предлагается множество других видов экскурсий и водных развлечений. Ниже приведён список самых распространённых экскурсий.</p><p>Наблюдение за манта-скатами Наблюдение за китами Наблюдение за дельфинами Кормление акул Кормление скатов Круиз на закате Круиз на рассвете Поездка на экватор</p><p>Катание на гидроцикле Катание на банане Катание на каяке Виндсёрфинг Парасейлинг Водные лыжи Катание на катамаране</p><figure><img src="legacy/images/articles/dolphin-cruise.webp" alt="maldives" loading="lazy" /></figure>', 'Что делать на Мальдивах | Путеводитель по Мальдивам | MTG', 'Топ-12 занятий на Мальдивах во время отпуска. Большинство из этих активностей доступны во всех курортах.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'most-famous-places-in-the-world'), 'article', 'ru', 'samye-znamenitye-mesta-v-mire', 'Самые знаменитые места в мире', 'Список самых известных мест и направлений в мире с фактами для туристов.', null, '<p>Автор: Шаяд Саид</p><p>Дата: 02.02.2021</p><p>В мире существуют сотни знаменитых мест, и из них я выделю топ-10 самых известных согласно моим исследованиям. Достопримечательности дают нам ощущение места. Эти исторические памятники и природные чудеса связывают нас с местом и побуждают его посетить. Эйфелева башня расположена в Париже, а статуя Свободы — в Нью-Йорке. Эти 10 достопримечательностей, каждая из которых значима для своего места и истории, должны быть в вашем списке желаемых путешествий.</p><figure><img src="legacy/images/articles/ar/famous-places-in-the-world.webp" alt="famous places in the world" loading="lazy" /></figure><h4>Бурдж-Халифа, Дубай</h4><p>В Дубае, Объединённые Арабские Эмираты, Бурдж-Халифа — это небоскрёб. Это самое высокое сооружение и здание в мире с 2009 года, с общей высотой 829,8 м (чуть больше половины мили), превзошедшее прежний рекорд — Тайбэй 101. С Бурдж-Халифой связаны следующие рекорды:</p><p>Эти рекорды делают его одним из лучших мест в мире.</p><figure><img src="legacy/images/articles/ar/famous-places-on-the-world.webp" alt="famous places on the world" loading="lazy" /></figure><h4>Эйфелева башня, Франция</h4><p>Эйфелева башня, также известная как La Tour Eiffel по-французски, была центральным элементом Парижской выставки 1889 года. Она была построена для празднования столетия Французской революции и демонстрации всему миру промышленной мощи Франции. Позже она стала символом города по следующим причинам:</p><figure><img src="legacy/images/articles/ar/most-famous-places-in-the-world.webp" alt="most famous places in the world" loading="lazy" /></figure><h4>Сиднейский оперный театр</h4><p>Сиднейский оперный театр — это многофункциональный центр исполнительских искусств в Сиднее, Новый Южный Уэльс, Австралия, расположенный в Сиднейской гавани. Это одно из самых известных и характерных сооружений двадцатого века.</p><figure><img src="legacy/images/articles/ar/famous-destinations-in-the-world.webp" alt="famous destinations in the world" loading="lazy" /></figure><h4>Статуя Свободы: Нью-Йорк</h4><p>Статуя Свободы — одна из самых известных достопримечательностей США, расположенная в Нью-Йоркской гавани. Монумент был построен в 1886 году французским народом в знак дружбы между двумя странами и объявлен национальным памятником в 1924 году. К статуе можно добраться на пароме из Battery Park в Нижнем Манхэттене, который останавливается как на острове Эллис, так и на острове Либерти.</p><figure><img src="legacy/images/articles/ar/best-places-in-the-world.webp" alt="best places in the world" loading="lazy" /></figure><h4>Великая пирамида Гизы: Каир, Египет</h4><p>Великая пирамида Гизы и окружающие её пирамиды насчитывают более 4000 лет. Они находятся за пределами Каира, вдоль реки Нил. Построенные около 2500 г. до н.э. царём Хуфу, эти древние руины являются одним из Семи чудес древнего мира — и единственным из них, сохранившимся до наших дней.</p><figure><img src="legacy/images/articles/ar/famous-destinations.webp" alt="famous destinations" loading="lazy" /></figure><h4>Марина Бэй Сэндс, Сингапур</h4><p>Марина Бэй Сэндс — это отель и торговый район в деловом центре Сингапура. При открытии в 2010 году он был заявлен как самый дорогой в мире отдельно стоящий казино-комплекс, стоимостью 8 миллиардов сингапурских долларов (6,88 миллиарда долларов США), включая землю.</p><figure><img src="legacy/images/articles/ar/famous-places.webp" alt="famous places" loading="lazy" /></figure><h4>Тадж-Махал: Агра, Индия</h4><p>Тадж-Махал был построен для жены императора Шах-Джахана. ЮНЕСКО признало это здание, завершённое в 1648 году, лучшим образцом индо-исламской архитектуры. Тадж-Махал находится в городе Агра и доступен из столицы Нью-Дели часовым перелётом или трёхчасовой поездкой на поезде. Из-за большого количества посетителей этой достопримечательности лучше приезжать в будние дни. Восход солнца отбрасывает очаровательное сияние на белую мраморную конструкцию.</p><figure><img src="legacy/images/articles/ar/famous-places-to-visit-in-the-world.webp" alt="famous places to visit in the world" loading="lazy" /></figure><h4>Мальдивские острова</h4><p>Мальдивы — это цепь из 1200 островов, расположенных в Индийском океане. Мальдивы известны своей уникальностью и природной красотой. Из-за географического положения лучше всего посещать их с октября по май. По следующим причинам они считаются одним из лучших мест для посещения:</p><figure><img src="legacy/images/articles/ar/best-places-to-tavel-in-the-world.webp" alt="best places to tavel in the world" loading="lazy" /></figure><h4>Остров Бора-Бора</h4><p>Бора-Бора — небольшой остров у берегов Полинезии (длиной всего около 10 км и шириной чуть более 3 км). В его центре находится дремлющий вулкан, который переходит в густые джунгли, прежде чем впадает в лагуну бирюзового цвета. Эти детали делают его одним из лучших направлений для путешествий:</p><figure><img src="legacy/images/articles/ar/famous-places-to-travel-in-the-world.webp" alt="famous places to-travel in the world" loading="lazy" /></figure><h4>Южный остров, Новая Зеландия</h4><p>Южный остров Новой Зеландии полон величественных ландшафтов на каждом шагу и является объектом Всемирного наследия ЮНЕСКО. Следующие факты делают его одним из знаменитых мест для путешествий.</p>', 'Самые знаменитые места в мире | Путеводитель по Мальдивам | MTG', 'Список самых известных мест и направлений в мире с фактами для туристов.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-honeymoon-ultimate-romantic-getaway-guide'), 'article', 'ru', 'medovyi-mesyats-na-maldivah-polnyi-romanticheskii-gid', 'Медовый месяц на Мальдивах: полный путеводитель по романтическому отдыху', 'Полный путеводитель по медовому месяцу на Мальдивах — откройте лучшие романтические курорты, виллы на воде, пакеты и уникальные впечатления для идеального отдыха вдвоём в раю.', null, '<figure><img src="legacy/images/maldives-honeymoons.webp" alt="Romantic Maldives honeymoon couple on beach" loading="lazy" /></figure><p>Мальдивы по праву считаются бесспорным раем для молодожёнов, предлагая новобрачным изысканное сочетание природной красоты, уединения и романтики. Этот архипелаг из 1192 коралловых островов, разбросанных по Индийскому океану, довёл до совершенства искусство отдыха вдвоём, с курортами, специально созданными для создания незабываемых романтических впечатлений.</p><p>Что отличает Мальдивы от других тропических направлений — это их уникальная география: каждый курорт обычно занимает собственный частный остров, обеспечивая полную изолированность. Знаменитые виллы на воде, которые Мальдивы впервые внедрили, позволяют парам просыпаться под мягкий плеск волн под своей виллой и сразу же погружаться в кристально чистые лагуны.</p><p>Помимо физической красоты, мальдивские курорты специализируются на создании персонализированных романтических впечатлений. От частных пикников на песчаных банках до подводных обеденных залов, окружённых морской жизнью — возможности для создания особых моментов безграничны. Мусульманская культура страны означает, что публичные проявления чувств допускаются только на курортных островах, создавая сдержанную, интимную атмосферу, идеальную для молодожёнов.</p><h2>Почему Мальдивы — лучшее направление для медового месяца</h2><figure><img src="legacy/images/activities/virgin-islands-excursion.webp" alt="Private island in Maldives" loading="lazy" /></figure><p>Несколько ключевых факторов делают Мальдивы главным направлением для медового месяца в мире:</p><h4>1. Непревзойдённая приватность</h4><p>В отличие от переполненных пляжных направлений, мальдивские курорты предлагают настоящую изолированность. Большинство из них занимают частные острова всего с 50-150 виллами, что означает, что у вас часто будут целые участки пляжа только для себя. Курортные острова тщательно спроектированы для максимальной приватности, с растительными барьерами между номерами.</p><h4>2. Впечатление от виллы на воде</h4><p>Мальдивы изобрели концепцию роскошной виллы на воде. Современные версии включают стеклянные панели в полу, частные бассейны-инфинити и прямой доступ к лагуне. Прочитайте наш полный путеводитель по виллам на воде на Мальдивах, чтобы выбрать идеальный вариант.</p><h4>3. Романтика по системе «всё включено»</h4><p>Курорты специализируются на безупречных романтических впечатлениях. Дворецкие могут организовать всё — от сюрприза с предложением руки и сердца до празднования юбилея. Большинство предлагают специальные пакеты для медового месяца с включёнными романтическими дополнениями.</p><h4>4. Тёплая погода круглый год</h4><p>Со средней температурой 28-30°C и температурой воды около 27°C в течение всего года, Мальдивы всегда готовы к медовому месяцу. Хотя существует сезон дождей, ливни обычно непродолжительны.</p><h4>5. Несравненная морская жизнь</h4><p>Коралловые атоллы Мальдив создают идеальные условия для разнообразной морской жизни. Многие курорты имеют отличные собственные рифы, где можно заниматься снорклингом с черепахами, скатами и тропическими рыбами прямо от своей виллы.</p><h2>5 лучших курортов Мальдив для медового месяца</h2><figure><img src="legacy/resorts/four-seasons-huraa/images/four-seasons-maldives-at-kuda-huraa-sunset-water-bangalow1.webp" alt="Four Seasons Kuda Huraa overwater bungalow" loading="lazy" /></figure><h3>1. Four Seasons Resort Maldives at Kuda Huraa</h3><p>Этот легендарный отель задаёт стандарт для медового месяца на Мальдивах, предлагая:</p><ul><li>Недавно отреставрированные виллы на воде с круглосуточным обслуживанием дворецкого</li><li>Частные бассейны-инфинити в премиальных виллах</li><li>Всемирно известный спа с процедурными кабинетами на воде</li><li>Семь ресторанов, включая гриль морепродуктов у рифа</li><li>Бесплатные экскурсии к китовым акулам в зависимости от сезона</li></ul><p>Пакет для медового месяца: включает шампанское, массаж для пар, частный круиз на закате и романтический ужин (минимальное проживание 5 ночей)</p><p>Лучший выбор для: пар, желающих безупречного сервиса и роскоши</p><figure><img src="legacy/resorts/baros-island/images/baros-maldives-island-resort-beach-dinner.webp" alt="Baros Maldives beach dinner" loading="lazy" /></figure><h3>2. Baros Maldives</h3><p>Этот уютный бутик-курорт идеален для пар, ищущих приватность:</p><ul><li>Всего 75 вилл на небольшом частном острове</li><li>Виллы, укрытые пышной растительностью для максимальной приватности</li><li>Отличный собственный риф, доступный с пляжа</li><li>Знаменитый ресторан Lighthouse над лагуной</li><li>Персонализированные романтические впечатления</li></ul><p>Пакет для медового месяца: включает шампанское, корзину фруктов, 60-минутную спа-процедуру и частный ужин (минимальное проживание 4 ночи)</p><p>Лучший выбор для: пар, ценящих близость и природную красоту</p><h2>Пакеты для медового месяца на Мальдивах</h2><figure><img src="legacy/images/romantic-sunrise-breakfast.webp" alt="Romantic breakfast in Maldives" loading="lazy" /></figure><p>Почти все мальдивские курорты предлагают специальные пакеты для медового месяца. Обычно они требуют подтверждения заключения брака в течение последних 6-12 месяцев. Основные компоненты:</p><h4>Стандартные включения:</h4><ul><li>Приветственное шампанское и корзина фруктов</li><li>Романтическое украшение кровати</li><li>Массаж для пар (обычно 30-60 минут)</li><li>Специальный торт или десерт для медового месяца</li><li>Памятный сертификат или подарок</li></ul><h4>Премиальные дополнения:</h4><ul><li>Частный круиз на закате</li><li>Ужин на берегу под звёздами</li><li>Гарантированное повышение категории виллы</li><li>Фотосессия с профессиональным фотографом</li><li>Персонализированные экскурсии, такие как аренда частной яхты</li></ul><h2>Незабываемые романтические впечатления</h2><figure><img src="legacy/images/articles/ozen-maadhoo-underwater-restaurant.webp" alt="Underwater restaurant Maldives" loading="lazy" /></figure><h4>1. Подводный ужин</h4><p>Несколько курортов предлагают невероятные подводные рестораны, где можно обедать, окружённым морской жизнью. Самый известный из них — Ithaa в Conrad Maldives, первый в мире полностью стеклянный подводный ресторан.</p><figure><img src="legacy/images/stargazing-on-the-maldives-beach.webp" alt="Stargazing in Maldives" loading="lazy" /></figure><h4>2. Частное наблюдение за звёздами</h4><p>При минимальном световом загрязнении Мальдивы предлагают захватывающее ночное небо. Некоторые курорты предоставляют телескопы и астрономов, которые проведут вас по созвездиям, пока вы отдыхаете на своей частной террасе.</p>', 'Медовый месяц на Мальдивах: полный путеводитель по романтическому отдыху | Путеводитель по Мальдивам | MTG', 'Полный путеводитель по медовому месяцу на Мальдивах — откройте лучшие романтические курорты, виллы на воде, пакеты и уникальные впечатления для идеального отдыха вдвоём в раю.', 'published', 'claude')
